/**
 * assets.js — sprite cắt từ laser-maze-404.png (WebP data URL, tự sinh
 * bằng Chrome headless từ chính ảnh tham chiếu của người dùng).
 * Game vẫn chạy được khi ảnh chưa decode xong: render kiểm tra từng
 * key trong object trả về của loadSprites() và fallback nét vẽ cũ.
 */

export const URLS = {
  badge:
    "data:image/webp;base64,",
  blocker:
    "data:image/webp;base64,",
  filter:
    "data:image/webp;base64,",
  floor:
    "data:image/webp;base64,",
  mirrorBs:
    "data:image/webp;base64,",
  mirrorFs:
    "data:image/webp;base64,",
  receiver:
    "data:image/webp;base64,",
  source:
    "data:image/webp;base64,",
  splitter:
    "data:image/webp;base64,",
};

/**
 * Nạp toàn bộ sprite. Trả về object được điền dần khi từng ảnh decode
 * xong (bất đồng bộ). Gọi onAll(imgs) sau khi tất cả hoàn tất — an toàn
 * khi component đã destroy vì chỉ ghi vào object cục bộ.
 */
export function loadSprites(onAll) {
  const imgs = {};
  const jobs = [];
  for (const [key, url] of Object.entries(URLS)) {
    const im = new Image();
    im.decoding = "async";
    im.src = url;
    const done = im.decode ? im.decode() : new Promise((res) => { im.onload = res; });
    jobs.push(done.then(() => { imgs[key] = im; }).catch(() => {}));
  }
  if (onAll) Promise.all(jobs).then(() => onAll(imgs));
  return imgs;
}
